{
  "root": "main_stack",
  "state": {
    "risottoPhases": [
      {
        "Phase": "Prep",
        "Duration": "10-15 mins",
        "Key Action": "Chop vegetables, slice mushrooms, warm broth"
      },
      {
        "Phase": "Sauté",
        "Duration": "8-10 mins",
        "Key Action": "Brown mushrooms, sweat shallots, toast rice"
      },
      {
        "Phase": "Simmer",
        "Duration": "20-25 mins",
        "Key Action": "Add broth gradually, stir frequently to release starch"
      },
      {
        "Phase": "Rest",
        "Duration": "2-3 mins",
        "Key Action": "Remove from heat, beat in fat (mantecatura) for creaminess"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title",
        "overview_text",
        "plating_image",
        "context_heading",
        "context_text",
        "instructions_heading",
        "ingredients_list_heading",
        "ingredients_stack",
        "instructions_list_heading",
        "instruction_1_stack",
        "instruction_2_stack",
        "instruction_3_stack",
        "instruction_4_stack",
        "instruction_5_stack",
        "instruction_6_stack",
        "phases_heading",
        "phases_table",
        "arborio_image",
        "cooking_image",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Creamy Vegan Mushroom Risotto Overview",
        "variant": "h2"
      },
      "children": []
    },
    "overview_text": {
      "type": "Text",
      "props": {
        "text": "This recipe creates a rich, velvety risotto for 4 people without using dairy. The key to the creamy texture lies in the high starch content of Arborio rice and the agitation process (stirring), which releases that starch into the broth. We will use a mix of mushrooms for depth of flavor and finish with a \"mantecatura\" technique using vegan fat to emulsify the sauce."
      },
      "children": []
    },
    "plating_image": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000701_01_1_mushroom-risotto.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "context_heading": {
      "type": "Text",
      "props": {
        "text": "Kitchen & Ingredient Context",
        "variant": "h3"
      },
      "children": []
    },
    "context_text": {
      "type": "Text",
      "props": {
        "text": "This recipe assumes you have a heavy-bottomed pot or Dutch oven to distribute heat evenly. We assume the use of dry white wine (like Pinot Grigio or Sauvignon Blanc) to deglaze the pan, but you can substitute extra vegetable broth mixed with a teaspoon of lemon juice or white wine vinegar if you prefer an alcohol-free version. We also assume the use of store-bought low-sodium vegetable broth, but homemade stock works excellently."
      },
      "children": []
    },
    "instructions_heading": {
      "type": "Text",
      "props": {
        "text": "Step-by-Step Cooking Instructions",
        "variant": "h3"
      },
      "children": []
    },
    "ingredients_list_heading": {
      "type": "Text",
      "props": {
        "text": "Ingredients:",
        "variant": "h4"
      },
      "children": []
    },
    "ingredients_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "ingredient_1",
        "ingredient_2",
        "ingredient_3",
        "ingredient_4",
        "ingredient_5",
        "ingredient_6",
        "ingredient_7",
        "ingredient_8",
        "ingredient_9",
        "ingredient_10",
        "ingredient_11",
        "ingredient_12"
      ]
    },
    "ingredient_1": {
      "type": "Text",
      "props": {
        "text": "- 1.5 cups Arborio rice (do not rinse, as starch is needed)"
      },
      "children": []
    },
    "ingredient_2": {
      "type": "Text",
      "props": {
        "text": "- 5 to 6 cups vegetable broth (kept warm in a separate pot)"
      },
      "children": []
    },
    "ingredient_3": {
      "type": "Text",
      "props": {
        "text": "- 1 lb mixed mushrooms (cremini, shiitake, oyster), sliced"
      },
      "children": []
    },
    "ingredient_4": {
      "type": "Text",
      "props": {
        "text": "- 2 shallots, finely minced"
      },
      "children": []
    },
    "ingredient_5": {
      "type": "Text",
      "props": {
        "text": "- 3 cloves garlic, minced"
      },
      "children": []
    },
    "ingredient_6": {
      "type": "Text",
      "props": {
        "text": "- 0.5 cup dry white wine"
      },
      "children": []
    },
    "ingredient_7": {
      "type": "Text",
      "props": {
        "text": "- 3 tbsp olive oil (divided)"
      },
      "children": []
    },
    "ingredient_8": {
      "type": "Text",
      "props": {
        "text": "- 2 tbsp vegan butter (or extra olive oil)"
      },
      "children": []
    },
    "ingredient_9": {
      "type": "Text",
      "props": {
        "text": "- 0.25 cup nutritional yeast (optional, for cheesy flavor)"
      },
      "children": []
    },
    "ingredient_10": {
      "type": "Text",
      "props": {
        "text": "- 1 tbsp fresh thyme leaves"
      },
      "children": []
    },
    "ingredient_11": {
      "type": "Text",
      "props": {
        "text": "- Salt and black pepper to taste"
      },
      "children": []
    },
    "ingredient_12": {
      "type": "Text",
      "props": {
        "text": "- Fresh parsley for garnish"
      },
      "children": []
    },
    "instructions_list_heading": {
      "type": "Text",
      "props": {
        "text": "Instructions:",
        "variant": "h4"
      },
      "children": []
    },
    "instruction_1_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instruction_1_title",
        "instruction_1_text"
      ]
    },
    "instruction_1_title": {
      "type": "Text",
      "props": {
        "text": "1. Warm the Broth:",
        "variant": "body"
      },
      "children": []
    },
    "instruction_1_text": {
      "type": "Text",
      "props": {
        "text": "Pour the vegetable broth into a saucepan and keep it on a low simmer next to your main cooking pot. Cold broth shocks the rice and stops the cooking process, preventing the creamy texture from developing."
      },
      "children": []
    },
    "instruction_2_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instruction_2_title",
        "instruction_2_text"
      ]
    },
    "instruction_2_title": {
      "type": "Text",
      "props": {
        "text": "2. Sauté the Mushrooms:",
        "variant": "body"
      },
      "children": []
    },
    "instruction_2_text": {
      "type": "Text",
      "props": {
        "text": "In a large, heavy-bottomed pot or Dutch oven, heat 1 tbsp olive oil over medium-high heat. Add the sliced mushrooms and cook until browned and their liquid has evaporated, about 5-7 minutes. Remove mushrooms and set aside."
      },
      "children": []
    },
    "instruction_3_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instruction_3_title",
        "instruction_3_text"
      ]
    },
    "instruction_3_title": {
      "type": "Text",
      "props": {
        "text": "3. Sauté Aromatics & Toast Rice:",
        "variant": "body"
      },
      "children": []
    },
    "instruction_3_text": {
      "type": "Text",
      "props": {
        "text": "Add 1 tbsp olive oil to the same pot. Add minced shallots and cook until softened, about 3-4 minutes. Add minced garlic and cook for another minute until fragrant. Add the Arborio rice and stir constantly for 2-3 minutes until the edges of the grains are translucent but the center is still opaque."
      },
      "children": []
    },
    "instruction_4_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instruction_4_title",
        "instruction_4_text"
      ]
    },
    "instruction_4_title": {
      "type": "Text",
      "props": {
        "text": "4. Deglaze with Wine:",
        "variant": "body"
      },
      "children": []
    },
    "instruction_4_text": {
      "type": "Text",
      "props": {
        "text": "Pour in the dry white wine (or broth/lemon juice mixture) and stir, scraping up any browned bits from the bottom of the pot. Cook until the wine is almost completely absorbed by the rice."
      },
      "children": []
    },
    "instruction_5_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instruction_5_title",
        "instruction_5_text"
      ]
    },
    "instruction_5_title": {
      "type": "Text",
      "props": {
        "text": "5. Gradually Add Broth:",
        "variant": "body"
      },
      "children": []
    },
    "instruction_5_text": {
      "type": "Text",
      "props": {
        "text": "Begin adding the warm vegetable broth, one ladleful (about 0.5 cup) at a time. Stir frequently, allowing each addition of broth to be almost fully absorbed before adding the next. This process should take about 20-25 minutes. The constant stirring helps release the starch from the rice, creating a creamy texture. The rice should be al dente – tender but still with a slight bite."
      },
      "children": []
    },
    "instruction_6_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "instruction_6_title",
        "instruction_6_text"
      ]
    },
    "instruction_6_title": {
      "type": "Text",
      "props": {
        "text": "6. Finish & Serve:",
        "variant": "body"
      },
      "children": []
    },
    "instruction_6_text": {
      "type": "Text",
      "props": {
        "text": "Once the rice is cooked to your liking and the risotto is creamy, remove it from the heat. Stir in the reserved cooked mushrooms, vegan butter, nutritional yeast (if using), and fresh thyme. Season with salt and black pepper to taste. Cover and let it rest for 2-3 minutes (mantecatura). Garnish with fresh parsley and serve immediately."
      },
      "children": []
    },
    "phases_heading": {
      "type": "Text",
      "props": {
        "text": "Risotto Cooking Phases",
        "variant": "h4"
      },
      "children": []
    },
    "phases_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "Phase",
            "label": "Phase"
          },
          {
            "key": "Duration",
            "label": "Duration"
          },
          {
            "key": "Key Action",
            "label": "Key Action"
          }
        ],
        "statePath": "/risottoPhases",
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "arborio_image": {
      "type": "Image",
      "props": {
        "url": "../assets/arborio_rice.jpg",
        "fit": "contain"
      },
      "children": []
    },
    "cooking_image": {
